INSERT INTO `item_template_locale` (`ID`, `locale`, `Name`, `Description`) VALUES
(990101, 'ruRU', 'Свиток переброса', 'Позволяет перебросить способность или талант в режиме «Случайный путь».'),
(990201, 'ruRU', 'Громовая палка заклинателя', 'Огнестрельное оружие, настроенное на тайную магию. Заклинателям сюда.'),
(990202, 'ruRU', 'Длинный лук целителя', 'Натянут для тех, кто успевает лечить между залпами.'),
(990203, 'ruRU', 'Тяжёлый дротик полководца', 'Ответ солдата на угрозы издалека.'),
(990204, 'ruRU', 'Кольчуга оплота героя', 'Кольчуга для тех, кто принимает удары без щита и строевой выучки.'),
(990205, 'ruRU', 'Кольчужный шлем оплота героя', 'Шлем для защитников, которые не следуют обычаям.'),
(990206, 'ruRU', 'Рунные латы боевого мага', 'Латы с рунами проводимости. Тяжёлая броня и ещё более тяжёлые заклинания.'),
(990207, 'ruRU', 'Рунные рукавицы боевого мага', 'Рукавицы, не мешающие творить чары.'),
(990208, 'ruRU', 'Коготь искристого кулака', 'Для тех, кто творит чары костяшками пальцев.'),
(990209, 'ruRU', 'Кожаный жакет кровавого пыла', 'Мягкая кожа для воинов Света, нападающих из тени.'),
(990210, 'ruRU', 'Клеймор ветробега', 'Двуручный меч, уравновешенный для быстрых бойцов.'),
(990211, 'ruRU', 'Эгида тихой молитвы', 'Щит, наполненный целительной энергией.'),
(990212, 'ruRU', 'Боевая мантия бастиона героя', 'Соткано для заклинателей, которые сами лезут под удар.'),
(990250, 'ruRU', 'Вечноострый боевой клинок', 'Сила, выносливость и критический удар. Они всегда будут тебе впору.'),
(990251, 'ruRU', 'Вечноострый клык', 'Кинжал, который становится острее вместе с тобой.'),
(990252, 'ruRU', 'Вечноострый клинок чар', 'Лезвие, которое остреет с каждым выученным заклинанием.'),
(990253, 'ruRU', 'Вечноострый жнец', 'Две руки — и впереди долгая карьера.'),
(990254, 'ruRU', 'Вечноострый боевой посох', 'Посох заклинателя, который растёт вместе с владельцем.'),
(990255, 'ruRU', 'Вечноострый военный посох', 'Этим посохом бьют, а не проводят через него магию. Сила и выносливость.'),
(990256, 'ruRU', 'Вечноострый длинный лук', 'Ловкость и сила атаки для боя на расстоянии — навсегда.'),
(990257, 'ruRU', 'Вечноострый ручной громобой', 'Огнестрельное оружие, зависящее от интеллекта. Только Герой мог до такого додуматься.'),
(990258, 'ruRU', 'Неувядающий латный нагрудник', 'Полный латный доспех, проводящий силу заклинаний. Настоящая крепость.'),
(990259, 'ruRU', 'Неувядающие латные наплечники', 'Наплечники заклинателя в самой тяжёлой броне.'),
(990260, 'ruRU', 'Неувядающий кольчужный хауберк', 'Кольчуга, которая растёт вместе с рукой в ней.'),
(990261, 'ruRU', 'Неувядающие кольчужные наплечья', 'Сила и выносливость в кольчужном обрамлении.'),
(990262, 'ruRU', 'Неувядающая кожаная кираса', 'Лёгкая кожа для бойца с тяжёлым ударом.'),
(990263, 'ruRU', 'Неувядающее кожаное оплечье', 'Сила на плечах разведчика.'),
(990264, 'ruRU', 'Неувядающая матерчатая роба', 'Мантия, усиливающая силу атаки и ловкость. Другие не осмелились бы её надеть.'),
(990265, 'ruRU', 'Неувядающее матерчатое оплечье', 'Шёлковые наплечники для бойца с кинжалом.'),
(990266, 'ruRU', 'Неувядающий кольчужный жилет прозрения', 'Кольчуга, в которой интеллект и дух важнее грубой силы.'),
(990267, 'ruRU', 'Неувядающий кожаный жилет погибели', 'Кожаный доспех для заклинателя: подвижность без шёлка.'),
(990268, 'ruRU', 'Неувядающий большой плащ', 'Плащ для заклинателей, который растёт вместе с ними.'),
(990269, 'ruRU', 'Неувядающий боевой плащ', 'Плащ, который становится лучше с каждым твоим уровнем.'),
(990270, 'ruRU', 'Неиссякаемый фокус чар', 'Чистая сила заклинаний, подстраивающаяся под владельца.'),
(990271, 'ruRU', 'Неиссякающий хронометр', 'Чистая скорость. Всё получается быстрее.'),
(990272, 'ruRU', 'Неусыпное око', 'Чистый критический удар — каким бы оружием ты ни бил.'),
(990280, 'ruRU', 'Цепь освобождённого', 'Сила и интеллект на одной цепи. Выбирай что-то одно — или оставь оба.'),
(990281, 'ruRU', 'Подвеска раздвоенной цели', 'Для тех, кто сперва наносит удар, а затем лечит рану.'),
(990282, 'ruRU', 'Кольцо размытой грани', 'Сила и сила заклинаний сплавлены в одном кольце.'),
